        input_data = raw_input()

    n = int(input_data.split()[0])
    planets = []
    idx = 1
    for i in range(n):
        coords = [int(input_data.split()[idx + 3*j]) for j in range(3)]
        planets.append(coords)
        idx += 3

    def dist2(p, q):
        return (p[0] - q[0])**2 + (p[1] - q[1])**2 + (p[2] - q[2])**2

    def dist(p, q):
        return math.sqrt(dist2(p, q))

    def in_sphere(p, center, r):
        return dist2(p, center) <= r**2 + 1e-9

    def dist2_distinct(p1, p2):
        return dist2(p1, p2)

    def get_midpoint(p1, p2):
        return ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2, (p1[2] + p2[2]) / 2)

    def get_midpoint_dist2(p1, p2):
        return ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2, (p1[2] + p2[2]) / 2)

    def sphere_from_2_points(p1, p2):
        center = get_midpoint(p1, p2)
        r = math.sqrt(dist2_distinct(p1, p2)) / 2
        return center, r

    def sphere_from_3_points(p1, p2, p3):
        def almost_zero(x):
            return abs(x) < 1e-10

        x1, y1, z1 = p1
        x2, y2, z2 = p2
        x3, y3, z3 = p3

        d12 = almost_zero(dist2_distinct(p1, p2))
        d13 = almost_zero(dist2_distinct(p1, p3))
        d23 = almost_zero(dist2_distinct(p2, p3))

        if d12 == 0 or d13 == 0 or d23 == 0:
            return (p1[0], p1[1], p1[2]), 0

        ab = math.sqrt(dist2_distinct(p1, p2))
        ac = math.sqrt(dist2_distinct(p1, p3))
        bc = math.sqrt(dist2_distinct(p2, p3))

        if ab + ac < bc or ab + bc < ac or ac + bc < ab:
            return (p1[0], p1[1], p1[2]), 0

        h = bc * dist2_distinct(p1, p2) / 2
        if almost_zero(h):
            return (p1[0], p1[1], p1[2]), 0

        area = (ab * bc * ac) / 4 * math.asin(math.sin(math.acos((ab**2 + ac**2 - bc**2)/(2 * ab * ac))))

        if almost_zero(area):
            return (p1[0], p1[1], p1[2]), 0

        center = (
            (p1[0] + (bc**2 * p2[0] + bc**2 * p3[0]) / (8 * area)) * 2,
            (p1[1] + (bc**2 * p2[1] + bc**2 * p3[1]) / (8 * area)) * 2,
            (p1[2] + (bc**2 * p2[2] + bc**2 * p3[2]) / (8 * area)) * 2
        )

        r = dist(p1, center)
        return center, r

    def sphere_from_4_points(p1, p2, p3, p4):
        def almost_equal(a, b):
            return abs(a - b) < 1e-9

        def determinant(vals):
            a, b, c = vals[0]
            d, e, f = vals[1]
            g, h, i = vals[2]
            return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)

        xs = [p1[0], p2[0], p3[0], p4[0]]
        ys = [p1[1], p2[1], p3[1], p4[1]]
        zs = [p1[2], p2[2], p3[2], p4[2]]
        ones = [1.0, 1.0, 1.0, 1.0]
        sq2 = [dist2(p1, p1), dist2(p2, p1), dist2(p3, p1), dist2(p4, p1)]

        detX = determinant([[ys, zs, ones, sq2]])
        detY = determinant([[xs, zs, ones, sq2]])
        detZ = determinant([[xs, ys, ones, sq2]])

        detS = determinant([[xs, ys, zs, ones]])

        if almost_equal(detS, 0):
            avg = [(x1 + x2 + x3 + x4) / 4, (y1 + y2 + y3 + y4) / 4, (z1 + z2 + z3 + z4) / 4]
            return avg, math.sqrt(max(dist2(avg, p1), dist2(avg, p2), dist2(avg, p3), dist2(avg, p4)))

        detS = abs(detS)

        if determinant([[xs[0], ys[0], zs[0], ones[0]], [xs[1], ys[1], zs[1], ones[1]], [xs[2], ys[2], zs[2], ones[2]], [xs[3], ys[3], zs[3], ones[3]]]) == 0:
            center = (0, 0, 0)
        else:
            center = (detX / detS, detY / detS, detZ / detS)

        r = dist(p1, center)
        return center, r

    def trivial_sphere(points):
        if not points:
            return (0.0, 0.0, 0.0), 0.0
        if len(points) == 1:
            return points[0], 0.0
        if len(points) == 2:
            return sphere_from_2_points(points[0], points[1])
        if len(points) == 3:
            return sphere_from_3_points(points[0], points[1], points[2])
        if len(points) == 4:
            return sphere_from_4_points(points[0], points[1], points[2], points[3])
        raise Exception("Trivial sphere: too many points")

    def welzl(points, R):
        random.shuffle(points)
        if len(points) == 0 or len(R) == 4:
            return trivial_sphere(R)

        p = points.pop(0)
        D, r = welzl(points, R)

        if in_sphere(p, D, r):
            return D, r
        else:
            D2, r2 = welzl(points, R + [p])
            return D2, r2

