import sys
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 4:
        return "-1"

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    second_line = lines[1].split()
    s, t = int(second_line[0]), int(second_line[1])

    roads = []
    for i in range(m):
        line_idx = 2 + i
        if line_idx >= len(lines):
            break
        parts = lines[line_idx].split()
        if len(parts) >= 3:
            x, y, w = int(parts[0]), int(parts[1]), int(parts[2])
            roads.append((x, y, w, i + 1))  # store 1-indexed index

    def check_connected(u, v, blocked_edges):
        """Check if u and v are still connected after blocking edges"""
        if u == v:
            return True

        # Build adjacency list, excluding blocked edges
        adj = [[] for _ in range(n + 1)]
        for road_idx in range(roads):
            road_num, (start, end, w) = road_idx, roads[road_idx][:3]
            if road_idx in blocked_edges:
                continue
            adj[start].append(end)
            adj[end].append(start)

        # BFS from u to see if v is reachable
        visited = [False] * (n + 1)
        queue = deque([u])
        visited[u] = True

        while queue:
            curr = queue.popleft()
            if curr == v:
                return False  # v is reachable from u
            for neighbor in adj[curr]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return True  # v is not reachable from u

    def check_connectivity(blocked_edges):
        """Check if s and t are disconnected after blocking edges"""
        return check_connected(s, t, blocked_edges)

    # Try 0 edges - already disconnected?
    if check_connectivity(set()):
        return "0\n0\n"

    # Try 1 edge - find minimum cost single road to disconnect s and t
    min_cost_1 = float('inf')
    best_1 = None
    blocked = set()
    for i, (u, v, w, idx) in enumerate(roads):
        blocked.add(i)
        if check_connectivity(blocked):
            if w < min_cost_1:
                min_cost_1 = w
