def get_prime_factors(x):
    factors = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return factors

def max_flow_dinic(n, source, sink, graph):
    level = {}
    ptr = {}
    edge_list = [graph[u] for u in range(n)]

    def bfs(s, t):
        for i in range(n):
            level[i] = -1
        level[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v in edge_list[u]:
                if graph[v][0][u] > 0 and level[v] == -1:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[s] > 0 and t in level

    def dfs(u, flow, t):
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u]):
            v = edge_list[u][i][0]
            cap = edge_list[u][i][1]
            if level[v] == level[u] + 1 and cap > 0:
                pushed = dfs(v, min(flow, cap), t)
                if pushed > 0:
                    return pushed
        return 0

    total_flow = 0
    while bfs(source, sink):
        for i in range(n):
            ptr[i] = 0
        while True:
            pushed = dfs(source, float('inf'), sink)
            if pushed == 0:
                break
            total_flow += pushed
    return total_flow

