            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Build MST
    mst_adj = [[] for _ in range(n + 1)]
    edges_in_mst = set()

    for w, u, v, idx in sorted_edges:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            edges_in_mst.add(idx)

    # Build tree structure for binary lifting
    parent_tree = [0] * (n + 1)
    depth = [0] * (n + 1)
    weight_to_parent = [0] * (n + 1)

    def dfs(u, p, d):
        parent_tree[u] = p
        depth[u] = d
        for v, w in mst_adj[u]:
            if v != p:
                weight_to_parent[v] = w
                dfs(v, u, d + 1)

    dfs(1, 0, 0)

    # Binary lifting tables
    LOG = 18
    up = [[0] * LOG for _ in range(n + 1)]
    max_w = [[0] * LOG for _ in range(n + 1)]

    for i in range(1, n + 1):
        up[i][0] = parent_tree[i]
        max_w[i][0] = weight_to_parent[i]

    for j in range(1, LOG):
        for i in range(1, n + 1):
            if up[i][j-1] != 0:
                mid = up[i][j-1]
                up[i][j] = up[mid][j-1]
                max_w[i][j] = max(max_w[i][j-1], max_w[mid][j-1])
            else:
                up[i][j] = 0
                max_w[i][j] = max_w[i][j-1]

    # Query maximum edge weight on path between u and v in MST
    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        res = 0
        for j in range(LOG):
            if (depth[u] - depth[v]) & (1 << j):
                res = max(res, max_w[u][j])
                u = up[u][j]

        if u == v:
            return res

        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                res = max(res, max_w[u][j])
                res = max(res, max_w[v][j])
                u = up[u][j]
                v = up[v][j]

        res = max(res, max_w[u][0])
        res = max(res, max_w[v][0])
        return res

    # Output results for non-MST edges in original order
    output = []
    for w, u, v, idx in edge_info:
        if idx not in edges_in_mst:
            max_on_path = query_max(u, v)
            output.append(str(max_on_path))

    return '\n'.join(output)

import os

def is_gp(arr):
    """Check if arr forms a geometric progression"""
    n = len(arr)
    if n <= 2:
        return True
    if all(x == 0 for x in arr):
        return True

    # Find first non-zero element
    first = None
    for i, x in enumerate(arr):
        if x != 0:
            first = i
            break

    # All zeros case handled above, so first exists
    assert first is not None

    c = arr[first]

    # Check elements from first onwards
    if first + 1 < n and arr[first + 1] == 0:
        # Ratio is 0, all subsequent elements must be 0
        if first + 2 < n:
            for i in range(first + 2, n):
                if arr[i] != 0:
                    return False
        return True
    elif first + 1 < n:
        # Calculate ratio
        b = arr[first + 1] / c
    else:
        # Only one element after first, valid GP
        return True

    # Verify remaining elements
    for i in range(first + 2, n):
        expected = c * (b ** (i - first))
        if abs(arr[i] - expected) > 1e-9:
            return False

    return True

