        result = []
        for i in range(1, n + 1):
            if not visited[i]:
                size = 0
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    size += 1
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
                result.append(size)
        return result

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    component_sizes = get_components(n, adj)

    # Generate all lucky numbers up to n
    lucky_numbers = []
    def generate_lucky(current, n_max):
        if current == 0:
            return
        if current > n_max:
            pass
        lucky_numbers.append(current)
        if current * 10 + 4 <= n_max:
            generate_lucky(current * 10 + 4, n_max)
        if current * 10 + 7 <= n_max:
            generate_lucky(current * 10 + 7, n_max)

    generate_lucky(0, n)

    # DP: dp[v] = minimum number of components needed to sum to v
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    # Classic knapsack (0/1) - each component used once
    for size in component_sizes:
        for v in range(n, size - 1, -1):
            if dp[v - size] != INF:
                dp[v] = min(dp[v], dp[v - size] + 1)

    # Also handle case where we have exactly one component that's already lucky
    for size in component_sizes:
        dp[size] = min(dp[size], 1)

    # Find minimum roads needed to make a lucky region
    # If we use k components to make a lucky region, we need k-1 roads
    ans = INF
    for lucky_num in lucky_numbers:
        if lucky_num <= n and dp[lucky_num] != INF and dp[lucky_num] >= 1:
            roads = dp[lucky_num] - 1
            ans = min(ans, roads)

    if ans == INF:
        return "-1\n"

    return str(ans) + "\n"

