def mat_mul(A, B):
    return [[sum(A[i][k] * B[k][j] % MOD for k in range(3)) % MOD for j in range(3)] for i in range(3)]

def mat_pow(A, p):
    result = [[1 if i == j else 0 for j in range(3)] for i in range(3)]
    base = [row[:] for row in A]
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        p //= 2
    return result

