    if n == 2:
        return str(f2 % MOD)
    if n == 3:
        return str(f3 % MOD)

    # Matrix for tribonacci sequence: [a, b, c] -> [b, c, a+b+c]
    M = [[0, 1, 0],
         [0, 0, 1],
         [1, 1, 1]]

    M_pow = mat_pow(M, n - 3)

    def get_coeff(initial_vec):
        """Given initial [v1, v2, v3] for (A_1, A_2, A_3), compute A_n"""
        result = [0, 0, 0]
        for i in range(3):
            for j in range(3):
                result[i] = (result[i] + initial_vec[j] * M_pow[j][i]) % MOD
        return result[0]  # After applying M^(n-3) to [A_1, A_2, A_3], first component is A_n

    # A_n: exponent of f_1
    A = get_coeff([1, 0, 0])
    # B_n: exponent of f_2  
    B = get_coeff([0, 1, 0])
    # C_n: exponent of f_3
    C = get_coeff([0, 0, 1])

    # E_n = total exponent of c, satisfying E_1=E_2=E_3=0, E_4=2, E_n = (2n-6) + E_{n-1} + E_{n-2} + E_{n-3}
    E = [0, 0, 0, 2]  # Base cases up to n=4
    for i in range(5, n + 1):
        E_i = (2 * i - 6 + E[i - 1] + E[i - 2] + E[i - 3]) % (MOD - 1)
        E.append(E_i)

    c_exp = E[-1]

    result = pow(f1, A, MOD)
    result = (result * pow(f2, B, MOD)) % MOD
    result = (result * pow(f3, C, MOD)) % MOD
    result = (result * pow(c, c_exp, MOD)) % MOD

    return str(result)

