def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    if m == 2:
        return 1 if a % 2 == 1 else 0
    gcd, x, _ = extended_gcd(a % m, m)
    if gcd != 1:
        return None
    return (x % m + m) % m

def mod_inv_table(n, p):
    inv1 = 1
    inv2 = 2
    table = [0] * n
    if p == 2:
        table[1] = 1
    else:
        table[1] = 1
        inv2 = (2 * (p // 2)) % p  # 2 * inv ≡ 1 (mod p)
        inv2 = mod_inverse(2, p)
        table[2] = inv2
    for i in range(3, n):
        table[i] = table[i-1] * inv2 % p
    return table

