        used = set()
        for t in types:
            if color[t] != 0:
                used.add(color[t])

        # Find smallest available colors
        next_c = 1
        while next_c in used:
            next_c += 1

        # Assign colors to ice creams at this vertex (greedy with sorting for stability)
        types_sorted = sorted(types)
        assigned_new = 0

        for t in types_sorted:
            if color[t] == 0:
                color[t] = next_c
                assigned_new += 1
                next_c += 1
            else:
