import os
import sys

def calculate_coprime(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def simplify(frac_x, frac_y):
    g = gcd(frac_x, frac_y)
    return (frac_x // g, frac_y // g)

def can_be_collinear(a1, b1, c1, d1, a2, b2, c2, d2):
    # Point 1 original: (a1/b1, c1/d1)
    # Point 2 original: (a2/b2, c2/d2)
    # After moving, check if they can be collinear with origin
    # Either (x+1, y) or (x, y+1) each

    x1 = a1 / b1
    y1 = c1 / d1
    x2 = a2 / b2
    y2 = c2 / d2

