    for dx1 in [(x1+1, y1), (x1, y1+1)]:
        for dx2 in [(x2+1, y2), (x2, y2+1)]:
            px, py = dx1
            qx, qy = dx2

            # Check if (px, py) and (qx, qy) are collinear with (0,0)
            if px * qy == qx * py:
                return True
    return False

