        perm = []
        possible = True

        for position in range(1, N + 1):
            assigned = False

            # Range [1, position-K]: smaller values here
            if position - K >= 1:
                for val in range(1, position - K + 1):
                    if not used[val]:
                        used[val] = True
                        perm.append(val)
                        assigned = True
                        break

            if not assigned:
                # Range [position+K, N]: larger values here
                if position + K <= N:
                    for val in range(position + K, N + 1):
                        if not used[val]:
                            used[val] = True
                            perm.append(val)
                            assigned = True
                            break

            if not assigned:
                possible = False
                break

        if possible:
            results.append(" ".join(map(str, perm)))
        else:
            results.append("-1")

    return "\n".join(results)

