def is_valid_set(a, b, threshold):
    """Check if score (a,b) is valid and A wins"""
    if a <= b:
        return False
    if a < threshold:
        return False
    # Clean win: b <= threshold-2
    # Deuce: b >= threshold-1 and a-b==2
    if b <= threshold - 2:
        return True
    if b >= threshold - 1 and a - b == 2:
        return True
    return False

