            for nv, e_new in reversed(adj[v]):
                if not used[e_new]:
                    pv = nv
                    e_idx_v = e_new
                    break

            if pv is not None:
                used[e_idx_v] = True
                # Form path: h-v-pv (edges are (h,v) and (v,pv))
                u_h, v_h = edges[edge_idx_h]
                # Either u_h or v_h is v (h is the other)
                # We want the path in format h-v-pv
                if u_h == v:
                    path = (v_h, v, pv)
                else:
                    path = (v_h, v, pv)
                ans.append(path)
            else:
