    d_factors = get_prime_factors(D)
    primes = sorted(d_factors.keys())

    max_mc = sum(d_factors.values())
    fact = [1] * (max_mc + 10)
    inv = [1] * (max_mc + 10)
    for i in range(1, max_mc + 10):
        fact[i] = (fact[i - 1] * i) % MOD
    inv[max_mc + 9] = modInverse(fact[max_mc + 9], MOD)
    for i in range(max_mc + 8, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def multinomial(counts_list):
        s = sum(counts_list)
        if s == 0:
            return 1
        num = fact[s]
        den = 1
        for c in counts_list:
            if c > 0:
                den = (den * fact[c]) % MOD
        return (num * den % MOD * inv[s]) % MOD

    def count_p(n, p):
        cnt = 0
        while n % p == 0:
            cnt += 1
            n //= p
        return cnt

    results = []
    num_primes = len(primes)

    for _ in range(q):
        try:
            v = int(next(iterator))
